import json
from datetime import datetime, date
from decimal import Decimal

def encode(o):
    if isinstance(o, (datetime, date)):
        return o.isoformat()
    if isinstance(o, Decimal):
        return str(o)          # preserve precision (never float!)
    raise TypeError(f"not serializable: {type(o).__name__}")

record = {
    "order_id": 42,
    "created": datetime(2026, 7, 2, 9, 15, 3),
    "amount": Decimal("19.99"),
}

text = json.dumps(record, default=encode)

# Reconstruct amount as Decimal on read via object_hook
def decode(d):
    if "amount" in d:
        d["amount"] = Decimal(d["amount"])
    return d

parsed = json.loads(text, object_hook=decode)

print(text)
print(parsed["amount"], type(parsed["amount"]).__name__)
